  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ “ਕਰਤਾਰ ਦੀ ਮਿਹਰ” ਨੂੰ ਕਿਸ ਤਰ੍ਹਾਂ ਮਿਹਨਤ ਨਾਲ ਜੋੜਿਆ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ 'ਚੱਲ ਏ ਜਵਾਨਾ' ਦੇ ਕੇਂਦਰੀ ਭਾਵ ਦੀ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਜਵਾਨਾਂ ਨੂੰ ਕਿਹੜਾ ਸੰਦੇਸ਼ ਦਿੰਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਦੱਸੀਆਂ ਗਈਆਂ ਨਕਾਰਾਤਮਕ ਭਾਵਨਾਵਾਂ (ਖੁੱਸਾ, ਗਿਲਾ, ਸਾੜਾ) ਕੀ ਹਨ ਅਤੇ ਇਹ ਸਮਾਜ 'ਤੇ ਕਿਹੋ ਜਿਹਾ ਪ੍ਰਭਾਵ ਪਾਉਂਦੀਆਂ ਹਨ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਦੂਰ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਰੌਣਕਾਂ ਵਿੱਚ ਬਦਲ ਦੇ ਸੋਹਣਿਆ ਉਜਾੜ ਨੂੰ' ਕਾਵਿ-ਪੰਕਤੀ ਦੀ ਪ੍ਰਸੰਗ ਸਹਿਤ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਇਸਦੇ ਡੂੰਘੇ ਅਰਥਾਂ ਨੂੰ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਮਨਾਂ ਵਿੱਚ ਉੱਗੇ ਖੂਬ ਫਸਲ ਪਿਆਰ ਦੀ' ਕਥਨ ਦਾ ਕੀ ਭਾਵ ਹੈ? ਸਮਾਜ ਵਿੱਚ ਪਿਆਰ ਦੀ ਫਸਲ ਉਗਾਉਣ ਦੇ ਕੀ ਲਾਭ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਅਨੁਸਾਰ, ਗਿਆਨਵਾਨ ਹੋ ਕੇ ਵਿਕਾਸ ਦੇ ਰਾਹ 'ਤੇ ਚੱਲਣ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ ਕਿਉਂ ਜ਼ਰੂਰੀ ਹੈ? ਇਸਦੇ ਸਮਾਜਿਕ ਅਤੇ ਵਿਅਕਤੀਗਤ ਲਾਭਾਂ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਗਨ, ਆਤਮ-ਵਿਸ਼ਵਾਸ ਅਤੇ ਦ੍ਰਿੜ੍ਹ ਨਿਸ਼ਚੇ ਮਨੁੱਖੀ ਜੀਵਨ ਵਿੱਚ ਕਿਵੇਂ ਮਹੱਤਵਪੂਰਨ ਭੂਮਿਕਾ ਨਿਭਾਉਂਦੇ ਹਨ? ਕਵਿਤਾ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਵਿਸਥਾਰ ਸਹਿਤ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਜਵਾਨਾਂ ਨੂੰ ਸੰਬੋਧਨ ਕਰਕੇ ਕਿਹੜੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਦਾ ਅਹਿਸਾਸ ਕਰਵਾਇਆ ਗਿਆ ਹੈ? ਸਮਾਜ ਸੁਧਾਰ ਵਿੱਚ ਜਵਾਨਾਂ ਦੀ ਭੂਮਿਕਾ 'ਤੇ ਚਾਨਣਾ ਪਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਕਰ ਸਾਰੇ ਜਵਾਨ ਆਪਣੇ ਦਿਲਾਂ ਵਿੱਚੋਂ ਖੁੱਸਾ, ਗਿਲਾ ਅਤੇ ਸਾੜਾ ਕੱਢ ਦੇਣ ਤਾਂ ਸਮਾਜ ਵਿੱਚ ਕਿਹੜੇ ਸਕਾਰਾਤਮਕ ਬਦਲਾਅ ਆ ਸਕਦੇ ਹਨ? ਵਿਸਥਾਰ ਨਾਲ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ 'ਗਿਆਨ ਅਤੇ ਵਿਗਿਆਨ' ਨੂੰ ਅਸਲੀ ਹਥਿਆਰ ਕਿਉਂ ਕਿਹਾ ਗਿਆ ਹੈ? ਅਜੋਕੇ ਸਮੇਂ ਵਿੱਚ ਇਹਨਾਂ ਦੀ ਮਹੱਤਤਾ ਬਾਰੇ ਆਪਣੇ ਵਿਚਾਰ ਪ੍ਰਗਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ 'ਚੱਲ ਏ ਜਵਾਨਾ' ਇੱਕ ਪ੍ਰੇਰਨਾਦਾਇਕ ਰਚਨਾ ਹੈ। ਇਸ ਕਥਨ ਦੀ ਪ੍ਰਮਾਣਿਕਤਾ ਸਿੱਧ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਪਾਠਕਾਂ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
