  ('fb2b37e4-db8d-46e1-a54f-cd4e18f1f171', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੀਨੇ 'ਚ ਉਮੰਗ ਲੈ ਕੇ ਨਵੇਂ ਸੰਸਾਰ ਦੀ, ਚੱਲ ਐ ਜਵਾਨਾ! ਤੈਨੂੰ ਮੰਜ਼ਿਲ ਪੁਕਾਰਦੀ। ਆਸਾਂ ਨੂੰ ਗਲੋਂ ਲਾਹ ਕੇ ਸੁੱਟ ਪਰ੍ਹੇ ਦੂਰ ਤੂੰ, ਉੱਦਮਾਂ ਨੂੰ ਗਲ ਲਾ ਕੇ ਰੱਖਣਾ ਜ਼ਰੂਰ ਤੂੰ, ਦੇਖੀਂ ਫੇਰ ਮਿਹਰ ਕਿਵੇਂ ਹੁੰਦੀ ਕਰਤਾਰ ਦੀ, ਚੱਲ ਐ ਜਵਾਨਾ!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('780dc73e-9ae4-4d04-87f2-ec6df90e9f3c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੰਨਿਆ ਕਿ ਰਾਹਾਂ ਮੇਲ ਖੜ੍ਹੀਆਂ ਰੁਕਾਵਟਾਂ, ਸੱਚ ਦੱਸਾਂ ਪਾਂਧੀਆਂ ਨੂੰ ਹੋਣ ਨਾ ਥਕਾਵਟਾਂ, ਘਰ-ਘਰ ਗੱਲ ਚੱਲੇ ਤੇਰੀ ਰਫ਼ਤਾਰ ਦੀ, ਚੱਲ ਐ ਜਵਾਨਾ!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('08b17bc1-55d6-45a4-8e09-0e22316114f3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਵਿੱਦਿਆ ਜ਼ਰੂਰ ਲੈਣੀ ਗਿਆਨ-ਵਿਗਿਆਨ ਦੀ, ਇਹਦੇ ਨਾਲ ਸੋਝੀ ਆਉਂਦੀ ਰੰਗਲੇ ਜਹਾਨ ਦੀ, ਅਕਲਾਂ ਨੂੰ ਪੈਂਦੀ ਨਹੀਂ ਲੋੜ ਹਥਿਆਰ ਦੀ, ਚੱਲ ਐ ਜਵਾਨਾ!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
