  ('2a49efab-9789-4790-bdf3-8f24f352bb20', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੁਹਾਡੇ ਵਿਚਾਰ ਅਨੁਸਾਰ ਸਾਡੇ ਜੀਵਨ ਵਿੱਚ 'ਆਕਸ' ਸਭ ਤੋਂ ਵੱਡੀ ਰੁਕਾਵਟ ਕਿਉਂ ਬਣਦਾ ਹੈ? ਕਵਿਤਾ ਵਿੱਚ ਗਿਆਨ ਅਤੇ ਵਿਗਿਆਨ ਨੂੰ ਅਸਲੀ ਹਥਿਆਰ ਕਿਉਂ ਕਿਹਾ ਗਿਆ ਹੈ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('63683262-7935-4b10-b772-2f05c064cbd8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'b65b5e55-ecd7-4520-bc84-88283d3b327d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇ ਸਾਰੇ ਜਵਾਨ ਆਪਣੇ ਦਿਲਾਂ ਵਿੱਚੋਂ ਖੁੱਸਾ, ਗਿਲਾ ਅਤੇ ਸਾੜਾ ਕੱਢ ਦੇਣ ਤਾਂ ਸਮਾਜ ਵਿੱਚ ਕਿਹੜੇ ਬਦਲਾਅ ਆ ਸਕਦੇ ਹਨ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-468Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL);
